+// Sites: the kitchens Larder serves. Every location belongs to one site, and
+// a batch belongs to the site of its location. Items, suppliers, recipes and
+// dishes are shared by all sites. Domain functions that take a `site` only
+// see that site's stock; without one they see every site.
+import { AppError } from "../errors.js";
+
+/** The site every request uses unless it names another. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site id a location belongs to (locations without one are in "main"). */
+export function locationSite(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** True when `site` is undefined (every site) or the batch's location is in `site`. */
+export function inSite(store, batch, site) {
+  return site === undefined || locationSite(store, batch.location) === site;
+}
+
+/** True when a location exists and is in `site` (any site when undefined). */
+export function hasLocation(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && (site === undefined || (l.site ?? DEFAULT_SITE) === site));
+}
