@@ -0,0 +1,91 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { migrate } from "../src/db/migrations.js";
+import { app, seed } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// The seed as it was in schema 2: no sites, no site on locations.
+function schema2() {
+  const data = seed();
+  delete data.sites;
+  data.schemaVersion = 2;
+  data.locations = data.locations.filter((l) => l.site === "main").map(({ site, ...l }) => l);
+  return data;
+}
+
+test("schema 2 files open with every location in site main", () => {
+  const data = migrate(schema2());
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+  assert.equal(data.batches.length, schema2().batches.length);
+});
+
+test("the site comes from X-Larder-Site, main by default; unknown sites are 400", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: { "x-larder-site": "main" } })).body.find((i) => i.id === 1).onHand, 10);
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "attic" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /attic/);
+});
+
+test("stock, batches, alerts and value only see the request's site", async () => {
+  const { handle } = app();
+  const items = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(items.length, 6);
+  assert.ok(items.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring, []);
+  assert.equal(alerts.lowStock.length, 6);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("orders received at the annex make annex stock", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", headers: ANNEX, body: { supplierId: 2, lines: [{ itemId: 2, qty: 4 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send`, headers: ANNEX });
+  const wrong = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "HD-1", expires: null, location: "fridge" }] } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const ok = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "HD-1", expires: null, location: "annex-fridge" }] } });
+  assert.equal(ok.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: ANNEX })).body.onHand, 4);
+  const main = (await handle({ path: "/items/2" })).body;
+  assert.ok(main.batches.every((b) => b.location !== "annex-fridge"));
+  const cooked = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(cooked.status, 409);
+});
+
+test("stock-takes belong to the request's site", async () => {
+  const { handle } = app();
+  const other = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } });
+  assert.equal(other.body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX })).status, 404);
+  const annex = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(annex.status, 201);
+});
+
+test("nightly checks per site do not overwrite each other", async () => {
+  const { handle, store } = app();
+  store.data.items.find((i) => i.id === 1).minQty = 1000;
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: ANNEX });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: ANNEX });
+  const low = store.data.outbox.filter((m) => m.kind === "low_stock");
+  assert.equal(low.length, 2);
+  assert.match(low[0].subject, /^1 items below minimum at Main kitchen$/);
+  assert.match(low[1].subject, /Annex kitchen/);
+});
